import * as ts from 'typescript';
import { readdirSync, readFileSync, statSync } from 'fs';
import { join } from 'path';

/**
 * The sentinel over "every response-DTO field is classified".
 *
 * Structurally a sibling of `../iam/route-permission-sentinel.spec.ts`: it
 * parses source with the TypeScript compiler API and never imports or
 * executes a DTO file, because the question is "what decorator is written
 * here", not "what does this resolve to once loaded" — and the second one
 * cannot fail a build that never boots Nest.
 *
 * One question, one pass: does every `@ApiProperty`/`@ApiPropertyOptional`
 * field in every `*.dto.ts` under `src/modules` carry a `@Sensitivity(...)`,
 * or is it named on `MASK_EXEMPT`? A field with neither is invisible to
 * `MaskResponseInterceptor` — nothing masks it, toggle on or off.
 *
 * Field grain, not file grain: a file-grain skip goes on hiding every other
 * field in a class the day after one field in it gets classified, so
 * `MASK_EXEMPT` names each unclassified field individually as
 * `ClassName.fieldName`.
 */
const SRC = join(__dirname, '..', '..');

interface DtoFieldOccurrence {
  file: string;
  className: string;
  property: string;
}

function nameOf(d: ts.Decorator): string {
  const e = d.expression;
  if (ts.isCallExpression(e)) {
    const x = e.expression;
    return ts.isIdentifier(x) ? x.text : x.getText();
  }
  return ts.isIdentifier(e) ? e.text : e.getText();
}

function dtoFiles(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) out.push(...dtoFiles(full));
    else if (entry.endsWith('.dto.ts') && !entry.endsWith('.spec.ts')) {
      out.push(full);
    }
  }
  return out;
}

const API_PROPERTY_DECORATORS = ['ApiProperty', 'ApiPropertyOptional'];

/** Every `@ApiProperty`/`@ApiPropertyOptional` field in this file, and whether it also carries `@Sensitivity`. */
function collectFields(
  file: string,
): { className: string; property: string; classified: boolean }[] {
  const source = ts.createSourceFile(
    file,
    readFileSync(file, 'utf8'),
    ts.ScriptTarget.Latest,
    true,
  );
  const fields: { className: string; property: string; classified: boolean }[] =
    [];

  source.forEachChild((node) => {
    if (!ts.isClassDeclaration(node)) return;
    const className = node.name?.text ?? '?';

    for (const member of node.members) {
      if (!ts.isPropertyDeclaration(member)) continue;
      const decorators = ts.getDecorators(member) ?? [];
      const isApiProperty = decorators.some((d) =>
        API_PROPERTY_DECORATORS.includes(nameOf(d)),
      );
      if (!isApiProperty) continue;

      const propertyName = ts.isIdentifier(member.name)
        ? member.name.text
        : member.name.getText();
      const classified = decorators.some((d) => nameOf(d) === 'Sensitivity');
      fields.push({ className, property: propertyName, classified });
    }
  });

  return fields;
}

const ALL_DTO_FILES = dtoFiles(join(SRC, 'modules')).map((f) =>
  f.slice(SRC.length + 1).replace(/\\/g, '/'),
);

const UNCLASSIFIED: DtoFieldOccurrence[] = [];
for (const rel of ALL_DTO_FILES) {
  for (const field of collectFields(join(SRC, rel))) {
    if (!field.classified) {
      UNCLASSIFIED.push({
        file: rel,
        className: field.className,
        property: field.property,
      });
    }
  }
}

/**
 * Every `@ApiProperty`/`@ApiPropertyOptional` field still unclassified, as
 * `ClassName.fieldName`, generated in one pass over `src/modules` rather than
 * hand-picked. It can only ever get shorter, and only by a change that also
 * adds real `@Sensitivity` coverage.
 *
 * The trailing file comment on each entry is load-bearing: 36 class names are
 * reused verbatim across more than one `*.dto.ts` for unrelated shapes, so
 * `ClassName.fieldName` alone does not say which declaration a line covers.
 * Colliding names appear once per file, deliberately not deduplicated, and
 * the comparison below is a sorted array equality rather than a `Set` — a
 * `Set` would let a third file's unclassified `ContainerResourcesDto.cpu`
 * pass under the first two files' cover instead of failing the build.
 */
